 const handoverBody=()=> <Card title="Actual custody, acknowledged" icon={KeyRound}>
 <div className="journey-route"><div className="route-end"><span className="eyebrow">Outgoing</span><strong>{nameFor(people,receiver)}</strong><p>{nameFor(sites,actualSite)} · {localDateTimeLabel(shiftAt)}</p></div><div className="route-line"><ArrowRight/></div><div className="route-end"><span className="eyebrow">Incoming</span><strong>{nameFor(people,incoming)}</strong><p>{handover==='accepted'?'Acknowledged at 12:24 PM':'Acknowledgement required'}</p></div></div>
 <dl className="facts"><Fact label="Vehicle and key">Koru · KRU482 · K-14</Fact><Fact label="Observed condition">{condition}</Fact><Fact label="Odometer / fuel">{returnKm} km · {fuel}</Fact><Fact label="Evidence">{receiptSaved?'RC-311 · CHK-441 · BK-208':'No return receipt recorded'}</Fact></dl><div className="inline-divider"/>
 {handover==='none'?<Alert title="No shift handover has been sent">Choose the actual recipient and review the retained return evidence.</Alert>:handover==='accepted'?<Alert tone="success" title={nameFor(people,incoming)+' acknowledged custody'}>HO-87 · outgoing and incoming histories retained. This acknowledgement does not release a Maintenance hold.</Alert>:handover==='disputed'?<Alert tone="critical" title="Handover disputed · receipt remains unresolved">{dispute||'Securement kit not received.'} Mia Chen owns reconciliation; the expected recipient is not recorded as having accepted the items.</Alert>:<><Alert tone="warning" title={'Awaiting '+nameFor(people,incoming)+'’s acknowledgement'}>Selection of a recipient does not transfer accepted custody. Only the named recipient can accept or dispute.</Alert><div className="display-note mt-4">Preview acting as {nameFor(people,incoming)} · recipient perspective. Authentication is simulated.</div><div className="flex gap-3 mt-4"><Button onClick={()=>{setHandover('accepted');event('HO-87 accepted · '+nameFor(people,incoming)+' · 12:24 PM');notify('Recipient acknowledgement recorded once in preview')}}>Acknowledge receipt</Button><Button variant="outline" onClick={()=>{setDispute('');open('dispute')}}>Dispute handover</Button></div></>}
 {handover==='accepted'&&<Button variant="outline" className="mt-4" onClick={()=>notify('HO-87 was already acknowledged. No second custody event created.')}>Check acknowledgement</Button>}
 {handover==='disputed'&&<Button variant="outline" className="mt-4" onClick={()=>{setReason('Securement kit receipt disputed; contact outgoing and incoming workers.');open('exception')}}>Assign reconciliation</Button>}
 </Card>;
 const rows=[
  {id:activeRequestId,title:request.purpose,person:displayName,site:nameFor(sites,request.site),when:localDateTimeLabel(request.start).replace(' · Pacific/Auckland',''),need:'Wheelchair position · escort',state:label,owner:'Mia Chen',next:stage==='requested'?'Assess request':stage==='assessed'?'Allocate resources':allocated?'Open linked journey':'View outcome'},
  {id:'TR-1043',title:'Community garden',person:limited?'Passenger context restricted':'Jordan Lee',site:'Kōwhai House',when:'Mon 28 Sep · 10:00 AM',need:'Support needs not confirmed',state:'Needs information',owner:'Eli Thompson',next:'Confirm support needs'},
  {id:'TR-1037',title:'Shopping trip',person:limited?'Passenger context restricted':'Authorised outing',site:'Aurora House',when:'Mon 28 Sep · 1:00 PM',need:'2 passengers · standard seats',state:'Allocated',owner:'Sara Wilson',next:'Open linked booking'},
  {id:'TR-1029',title:'Community visit',person:limited?'Passenger context restricted':'Authorised client',site:'Kōwhai House',when:'Fri 25 Sep · 2:00 PM',need:'Transport not available',state:'Not fulfilled',owner:'Eli Thompson',next:'Review recorded outcome'},
  {id:'TR-1024',title:'Library visit',person:limited?'Passenger context restricted':'Authorised client',site:'Aurora House',when:'Thu 24 Sep · 9:30 AM',need:'Client chose not to travel',state:'Cancelled',owner:'Mia Chen',next:'View client choice'}
 ].filter(r=>(siteFilter==='all'||r.site===siteFilter)&&(statusFilter==='all'||(statusFilter==='open'?!['Completed','Cancelled','Not fulfilled'].includes(r.state):['Completed','Cancelled','Not fulfilled'].includes(r.state)))&&[r.id,r.title,r.person,r.site,r.state].join(' ').toLowerCase().includes(query.toLowerCase()));
 const rowOpen=(r:any)=>r.id===activeRequestId?go(requestUrl):reference(r.id+' · '+r.title);
 const actionsFor=(r:any)=>[{label:'Open request',icon:ArrowUpRight,onClick:()=>rowOpen(r)},{label:'View source context',icon:Link2,onClick:()=>reference(r.id+' · source and return')}];
 const primaryAction=()=>{if(requestOutcome&&allocated&&!checkedOut){reference('Recorded outcome · reconcile the linked booking');return}if(stage==='requested')open('assess');else if(stage==='assessed')open('allocate');else if(stage==='allocated')open('checkout');else if(stage==='out')open('return');else if(stage==='returned')open('handover');else reference('Recorded outcome')};
 const actionLabel=requestOutcome&&allocated&&!checkedOut?'Review linked obligations':stage==='requested'?'Assess request':stage==='assessed'?'Allocate resources':stage==='allocated'?'Prepare for departure':stage==='out'?'Record return':stage==='returned'?'Hand over to next shift':'View outcome';
 const allocationProblem=()=>{if(scenario==='No policy configured')return 'Allocation needs configuration. Required checks, staffing eligibility, buffers and approval authority have not been established.';if(!vehicle||!driver||(request.escort&&!escort)||!kit)return 'Choose a suitable vehicle, driver and escort, then confirm the requested equipment.';if(driver===escort)return 'Driver and escort must be separate for this synthetic request.';if(['Stale allocation','Allocation conflict'].includes(scenario)&&!refresh)return scenario==='Stale allocation'?'This assessment is out of date. Refresh availability before allocating. Your selections are retained.':'Koru is now busy for this period. No booking or journey was created. Review the conflict and choose a suitable alternative or another time.';return ''};
 const run=(fn:()=>void)=>{if(actionLock.current)return;actionLock.current=true;setBusy(true);setTimeout(()=>{fn();setBusy(false);actionLock.current=false},500)};
 const submit=()=>{
  setError('');
  if(modal==='request'){if(created){setError('This preview already created TR-1044. Open the existing request to avoid a duplicate.');return}if(!draft.client||!draft.purpose.trim()||!draft.destination.trim()){setStep(0);setError('Choose a client and enter a purpose and destination.');return}if(!validLocalDateTime(draft.start)||!validLocalDateTime(draft.end)||draft.end<=draft.start){setStep(1);setError('Choose a complete time window with return after pickup.');return}run(()=>{setRequest(draft);setRequestOutcome('');setCreated(true);setAllocationSaved(false);setVehicle('');setDriver('');setEscort('');setKit(false);setCheckedOut(false);setReceiptSaved(false);setHandover('none');setCheckSaved(false);setStage('requested');setSuccess(true);setDirty(false);event('Request TR-1044 saved in preview · no resources assigned')});return}
  if(modal==='assess'){if(!assessed){setError('Confirm that the permitted request information has been assessed.');return}setStage('assessed');setSuccess(true);setDirty(false);event('Assessed · Mia Chen · awaiting allocation');return}
  if(modal==='allocate'){const p=allocationProblem();if(p){setError(p);return}run(()=>{if(scenario==='Allocation response lost'&&!allocationSaved){setAllocationSaved(true);setError('The response was interrupted. The allocation may have saved. Check the original attempt before retrying.');return}setStage('allocated');setSuccess(true);setDirty(false);if(!allocationSaved)event('Allocated · BK-208 and J-608 linked to '+activeRequestId);setAllocationSaved(true)});return}
  if(modal==='checkout'){if(requestOutcome){setError('This request has a recorded outcome. Reconcile the linked booking and passenger plan before departure.');return}if(maintenance||scenario==='Failed pre-use check'){setError('Departure is blocked by a failed check. Report or link the issue to Maintenance.');return}if(['Missing keys','Unexpected holder / site','Missing equipment'].includes(scenario)){setError('Custody needs reconciliation. Record an owned exception before continuing.');return}if(!checkSaved||!checks.passenger||!checks.keys||!checks.equipment||!giver||!receiver||!actualSite||!validLocalDateTime(observedAt)||!odometer||Number(odometer)<48216){setError('Complete the original check, passenger confirmation, keys, equipment and actual handover details. Odometer must be at least 48,216 km; a lower reading needs correction review.');return}run(()=>{setCheckedOut(true);setStage('out');setSuccess(true);setDirty(false);event('Checked out · K-771 · '+nameFor(people,giver)+' → '+nameFor(people,receiver)+' · '+localDateTimeLabel(observedAt))});return}
  if(modal==='return'){if(!returnKm||Number(returnKm)<Number(odometer)||!condition.trim()||!validLocalDateTime(observedAt)||!giver||!receiver||!actualSite){setError('Check the observed return details. Return odometer cannot be below checkout; record a correction for an incorrect reading.');return}run(()=>{if(scenario==='Return receipt retry'&&!receiptSaved){setReceiptSaved(true);setError('Receipt acknowledgement was interrupted. Check receipt RC-311 before sending again.');return}setReceiptSaved(true);setStage('returned');setSuccess(true);setDirty(false);event('Return receipt RC-311 · observations retained · custody checked separately')});return}
  if(modal==='handover'){if(!receiptSaved){setError('Record the observed return receipt before this handover. No receipt or accepted custody can be inferred from the booking.');return}if(!incoming||incoming===receiver||!validLocalDateTime(shiftAt)){setError('Choose a recipient different from the actual giver and a complete observed handover time.');return}setHandover('pending');setSuccess(true);setDirty(false);event('Handover HO-87 sent to '+nameFor(people,incoming)+' · acknowledgement pending');return}
  if(modal==='cancel'){if(!reason.trim()){setError('Record the reason so the request history remains clear.');return}setRequestOutcome(outcome==='unavailable'?'Not fulfilled':outcome==='choice'?'Client chose not to travel':'Requester cancelled');if(!allocated)setStage(outcome==='unavailable'?'not-fulfilled':'cancelled');event((outcome==='choice'?'Client chose not to travel':outcome==='requester'?'Requester cancelled':'No suitable transport')+' · '+reason);setSuccess(true);setDirty(false);return}
  if(modal==='exception'){if(!reason.trim()){setError('Describe what needs resolving.');return}setHandover('exception');setSuccess(true);setDirty(false);event('Owned exception · Mia Chen · '+reason);return}
  if(modal==='problem'){if(!reportText.trim()){setError('Describe the issue.');return}if(!maintenanceFailed){setMaintenanceFailed(true);setError('Simulated link response failed. Your report and evidence are retained; retry the same report.');return}setMaintenance(true);setSuccess(true);setDirty(false);event('Maintenance M-318 linked · source check CHK-441 · restriction retained');return}
 };
 const queue=()=>{
 if(scenario==='Loading queue')return <Card><div role="status" aria-label="Loading transport requests"><div className="skeleton-line"/>{[1,2,3,4].map(i=><div key={i} className="skeleton-line" style={{height:46,width:'100%'}}/>)}</div><Button variant="outline" onClick={()=>setScenario('Normal journey')}>Finish simulated load</Button></Card>;
 if(scenario==='Queue load failed')return <Card><EmptyState icon={AlertTriangle} title="Transport requests could not load" description="Your filters are retained. No empty or zero-total result is implied." action={<Button onClick={()=>{setScenario('Normal journey');notify('Requests reloaded in preview')}}>Retry loading</Button>}/></Card>;
 if(scenario==='Empty queue'||!rows.length)return <Card><EmptyState icon={Inbox} title="No requests match this view" description="Try another filter, or request transport before a vehicle or driver is known." action={<Button onClick={()=>{setQuery('');setSiteFilter('all');setStatusFilter('all');if(scenario==='Empty queue')setScenario('Normal journey')}}>Clear filters</Button>} secondaryAction={<Button variant="outline" onClick={()=>open('request')}>Request transport</Button>}/></Card>;
 if(tab==='journeys')return <><Card title="Linked journey" icon={Route}>{allocated?<><div className="source-row"><div><strong>{request.purpose} · J-608</strong><small>{activeRequestId} → BK-208 → J-608 · {label}</small></div><Button onClick={()=>go(journeyUrl)}>Open journey<ArrowRight className="size-4"/></Button></div><Alert title="Completion follows source checks">Returning the vehicle does not mark passengers returned or resolve medication logistics.</Alert></>:<EmptyState icon={Route} title="No journey linked yet" description="Assess and allocate the request to link one vehicle booking and one actual journey." action={<Button onClick={()=>go(requestUrl)}>Open transport request</Button>}/>}</Card></>;
 if(tab==='custody')return <><Card title="Returns and handovers" icon={KeyRound}>{allocated?<><div className="source-row"><div><strong>Koru · KRU482</strong><small>{stage==='out'?'With Nia Patel · scheduled end 12:00 PM is not proof of return':receiptSaved?'Return receipt RC-311 · review custody':'Not checked out · prepare from the booking'}</small></div><Button onClick={()=>go(stage==='out'?journeyUrl:receiptSaved?'/fleet-assets/handovers/HO-87':bookingUrl)}>{stage==='out'?'Record return':receiptSaved?'Open handover':'Open booking'}</Button></div><Alert tone="warning" title="Custody follows actual acknowledgement">Missing keys, equipment or a disputed receipt remain with an accountable owner.</Alert></>:<EmptyState icon={KeyRound} title="No custody event for this request" description="The booking will show collection, return and acknowledged handover once resources are allocated." action={<Button onClick={()=>go(requestUrl)}>View request</Button>}/>}</Card></>;
 if(tab==='outings')return <Card title="Outing context" icon={Users}><div className="source-row"><div><strong>Shopping trip · OUT-42</strong><small>Aurora House · Mon 28 Sep · source-owned participant list</small></div><Button variant="outline" onClick={()=>reference('Outing OUT-42 · passenger accountability')}>Open outing context</Button></div><Alert title="The outing owns its participants">Transport links to the existing outing and permitted client records. Returning a vehicle never marks every passenger returned.</Alert></Card>;
 return <><div><div className="section-caption"><span>Transport requests <small>{rows.length} of {rows.length} matching records shown</small></span><span className="muted">Next action and accountable owner</span></div>{cards?<div className="cards-grid">{rows.map(r=><EntityCard key={r.id} name={r.title} subline={r.id+' · '+r.site} icon={Route} meridian={r.state==='Needs information'?'warning':'success'} actions={actionsFor(r)} onOpen={()=>rowOpen(r)} onContextMenu={e=>context.open(e,r)} chips={<><EntityChip>{r.when}</EntityChip><StatusBadge variant={r.state==='Needs information'?'warning':'neutral'}>{r.state}</StatusBadge></>} alerts={<span className="text-xs text-muted-foreground">{r.need}</span>} footer={{personName:r.owner,primary:r.owner,secondary:r.next}}/> )}</div>:<EntityTable rows={rows} rowKey={r=>r.id} identityLabel="Request / passenger" identityWidth="1.7fr" identity={r=>({name:r.title,subline:r.id+' · '+r.person,icon:Route})} columns={[{key:'when',label:'Window / site',width:'1.4fr',cell:r=><div><strong className="text-xs font-medium">{r.when}</strong><div className="text-[11px] text-muted-foreground">{r.site}</div></div>},{key:'state',label:'Status',width:'1.1fr',cell:r=><StatusBadge variant={r.state==='Needs information'?'warning':r.state==='Allocated'?'success':'neutral'}>{r.state}</StatusBadge>},{key:'owner',label:'Owner',width:'1fr',cell:r=><PersonCell name={r.owner}/>},{key:'next',label:'Next action',width:'1.15fr',cell:r=><span className="text-[12px] text-primary">{r.next}</span>}]} minWidth={880} onOpen={rowOpen} actionsFor={actionsFor} onRowContextMenu={(e,r)=>context.open(e,r)}/>}<div className="list-notice"><ShieldCheck className="size-3"/>Counts, search and rows use the same permitted scope. Synthetic records only.</div></div><div className="request-callout"><div className="icon"><ClipboardList className="size-6"/></div><div><h2>Start with the person’s transport need</h2><p>Record the time, pickup and support needed. Allocate a suitable vehicle and team after assessment.</p></div><Button variant="outline" onClick={()=>open('request')}>Request transport<Plus className="size-4"/></Button></div></>;
 };
 const entry=()=> <div className="record-grid frontline-surface"><div className="page-stack"><Card title={route==='/my-day'?'Your transport work':route.includes('/sites/')?'Transport at Aurora House':limited?'Transport context':'Transport for Alex'} icon={Route}><div className="step-row"><CalendarDays/><div><strong>{request.purpose} · {localDateTimeLabel(request.start)}</strong><p>{allocated?'Koru · BK-208 · prepare for departure':'Request '+activeRequestId+' · resources not assigned'}</p></div><Button onClick={()=>{setReturnRoute(route);go(allocated?bookingUrl:requestUrl)}}>{allocated?'Prepare for departure':'View request'}</Button></div><div className="step-row"><KeyRound/><div><strong>Shift custody</strong><p>{handover==='none'?'No handover sent for this request':handover==='accepted'?'Acknowledged by Ben Carter':'Receipt or handover needs attention'}</p></div><Button variant="outline" onClick={()=>{setReturnRoute(route);go('/fleet-assets/handovers/HO-87')}}>Open handover</Button></div></Card><Alert title="Context retained">Opening transport carries this entry point. The booking and journey provide a clear return to this {route==='/my-day'?'My Day view':route.includes('/sites/')?'site':'client'}.</Alert></div><Card title="Request transport" icon={Plus}><p className="muted mb-4">Record the need now. You can leave the vehicle and driver unassigned.</p><Button onClick={()=>open('request')}>Request from this context</Button><p className="footnote">Minimal entry demonstration. This does not redesign My Day, Client or Site.</p></Card></div>;
